// dp[i][c]: 앞의 물건 i개로 무게 c 이하에서 얻는 최대 가치
for (int i = 1; i <= n; i++)
    for (int c = 0; c <= W; c++) {
        dp[i][c] = dp[i - 1][c];
        if (c >= w[i]) dp[i][c] = max(dp[i][c], dp[i - 1][c - w[i]] + v[i]);
    }

// 1차원 배열 하나로 0/1 배낭 (각 물건은 한 번만)
for (int i = 1; i <= n; i++)
    for (int c = W; c >= w[i]; c--)          // 뒤에서부터
        dp[c] = max(dp[c], dp[c - w[i]] + v[i]);

